insert into tb_second_hand_product(
    id, seller_id, school_id, compus_id, category_id, title, description,
    condition_level, price, pickup_address_id, pickup_address_snapshot, pickup_only,
    negotiable, status, view_count, favorite_count, deleted, create_time, update_time
) values(
    null, #{sellerId}, #{schoolId}, #{compusId}, #{categoryId}, #{title}, #{description},
    #{conditionLevel}, #{price}, #{pickupAddressId}, #{pickupAddressSnapshot}, #{pickupOnly},
    #{negotiable}, #{status}, #{viewCount}, #{favoriteCount}, #{deleted}, #{createTime}, #{updateTime}
)

mapper.update:
update tb_second_hand_product
compus_id = #{compusId}, category_id = #{categoryId}, title = #{title}, description = #{description}, condition_level = #{conditionLevel}, price = #{price}, pickup_address_id = #{pickupAddressId}, pickup_address_snapshot = #{pickupAddressSnapshot}, pickup_only = #{pickupOnly}, negotiable = #{negotiable}, status = #{status}, view_count = #{viewCount}, favorite_count = #{favoriteCount}, deleted = #{deleted}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select 
from tb_second_hand_product p
left join tb_user u on p.seller_id = u.id
left join tb_school s on p.school_id = s.id
left join tb_compus cp on p.compus_id = cp.id
left join tb_second_hand_category c on p.category_id = c.id

    p.deleted = 0
    and p.school_id = #{schoolId}
    and p.status = #{query.status}
    and p.status = 0
    and p.category_id = #{query.categoryId}
    and p.compus_id = #{query.compusId}
    and p.condition_level = #{query.conditionLevel}
    and p.price >= #{query.minPrice}
    and p.price <= #{query.maxPrice}

        and (p.title like concat('%', #{query.keyword}, '%') or p.description like concat('%', #{query.keyword}, '%'))


order by p.create_time desc
